using GoblinCombat;
using System.Numerics;
using System.Text.Json;
using ByteEngine.Core.Animation;
using ByteEngine.Core.Assets;
using ByteEngine.Core.Assets.Importers;
using ByteEngine.Core.Graphics.ThreeD;
using ByteEngine.Core.Runtime;
using ByteEngine.Core.Scene;
internal static class MeleePack {
 internal const string Root="Assets/AnimationPacks/HumanMelee/";
 internal const string ModelPath="Assets/Models/Manny.glb";
 internal const string SwordPath=Root+"Models/Weapons/Human_Sword.fbx";
 internal static readonly Dictionary<string,string> Clips=new(){["AttackRight"]="Animations/Male/Combat/1H/HumanM@Attack1H01_R.fbx",["AttackLeft"]="Animations/Male/Combat/1H/HumanM@Attack1H01_L.fbx",["AttackTwoHanded"]="Animations/Male/Combat/2H/HumanM@Attack2H01.fbx",["GuardIdle"]="Animations/Male/Combat/1H/HumanM@CombatIdle1H01.fbx",["GuardTwoHanded"]="Animations/Male/Combat/2H/HumanM@CombatIdle2H01.fbx",["Run"]="Animations/Male/Movement/Run/HumanM@Run01_Forward.fbx",["Idle"]="Animations/Male/Idles/HumanM@Idle01.fbx",["Damage"]="Animations/Male/Combat/HumanM@CombatDamage01.fbx",["Death"]="Animations/Male/Combat/HumanM@Death01.fbx"};
 internal static void Configure(GameProjectRuntime runtime){var target=runtime.Assets.LoadModel(runtime.Database.ResolveReference(ModelPath));var sourceRig=runtime.Assets.LoadModel(runtime.Database.ResolveReference(Root+"Models/HumanM_Model.fbx"));var retargetReport=new List<object>();var grip=runtime.Assets.LoadModel(runtime.Database.ResolveReference(Root+"Animations/Masked Poses/Human@ObjectGripHands01.fbx")).Animations.First();var guard=runtime.Assets.LoadModel(runtime.Database.ResolveReference(Root+Clips["GuardIdle"])).Animations.First();bool Finger(string name)=>name.Contains("Finger",StringComparison.OrdinalIgnoreCase)||name.Contains("thumb",StringComparison.OrdinalIgnoreCase)||name.Contains("pinky",StringComparison.OrdinalIgnoreCase);
 foreach(var item in Clips){var reference=runtime.Database.ResolveReference(Root+item.Value);var source=runtime.Assets.LoadModel(reference);var clip=source.Animations.First();ImportedAnimationChannel Hold(ImportedAnimationChannel c)=>new(){NodeName=c.NodeName,Rotation=c.Rotation is {Keys.Count:>0} r?new ImportedQuaternionTrack{Keys=new(){r.Keys[0]}}:null};var channels=clip.Channels.Select(c=>Finger(c.NodeName)?grip.FindChannel(c.NodeName)??c:item.Key=="Run"&&new[]{"B-shoulder.R","B-upperArm.R","B-forearm.R","B-hand.R"}.Contains(c.NodeName)?Hold(guard.FindChannel(c.NodeName)??c):c).ToList();if(item.Key=="AttackRight"){File.WriteAllText(Program.Root+"/Preview/Pack rig transforms.json",JsonSerializer.Serialize(new {target=target.Nodes.Select(n=>new {n.Name,n.ParentKey,n.LocalTransform}),source=source.Nodes.Select(n=>new {n.Name,n.ParentKey,n.LocalTransform}),channels=clip.Channels.Select(c=>new{c.NodeName,rotation=c.Rotation?.Keys.FirstOrDefault(),translation=c.Translation?.Keys.FirstOrDefault()})},new JsonSerializerOptions{WriteIndented=true,IncludeFields=true}));}var compatible=new ImportedAnimation{Name=item.Key,Key=clip.Key,Duration=clip.Duration,Channels=channels};var baked=HumanoidClipBaker.Bake(sourceRig,target,compatible,HumanoidClipBaker.HumanMToManny(),item.Key);retargetReport.Add(new{item.Key,baked.MappedBones,baked.MaxPlanarTravel,baked.ScaleRatio});ModelOwnedAnimationStore.Bake(Program.Root,target,baked.Clip,item.Key,source.Guid,reference.CachedProjectPath,clip.Key,clip.Name,true);if(item.Key=="AttackRight")foreach(var alias in new[]{"ComboLight1","ComboLight2"})ModelOwnedAnimationStore.Bake(Program.Root,target,baked.Clip,alias,source.Guid,reference.CachedProjectPath,clip.Key,clip.Name,true);}
 File.WriteAllText(Program.Root+"/Preview/Manny retarget verification.json",JsonSerializer.Serialize(retargetReport,new JsonSerializerOptions{WriteIndented=true}));var report=new List<object>();var scene=new Scene("Pack pose analysis");var renderer=scene.CreateGameObject("Pack model").AddComponent(new SkeletalMeshRenderer{Model=runtime.Database.ResolveReference(ModelPath),PlayOnStart=false,Speed=0});renderer.ResolveRuntimeResources();foreach(string clip in new[]{"AttackRight","AttackLeft","AttackTwoHanded","GuardIdle","Run"}){renderer.Play(clip,false,0);var frames=new List<object>();for(int i=0;i<=24;i++){renderer.Seek(renderer.Duration*i/24);renderer.TryGetBoneWorldMatrix("hand.R",out var hand);renderer.TryGetBoneWorldMatrix("hand.L",out var left);renderer.TryGetBoneWorldMatrix("foot.R",out var foot);frames.Add(new{t=renderer.PlaybackTime,right=hand.Translation.ToString(),left=left.Translation.ToString(),foot=foot.Translation.ToString(),hand=new[]{hand.M11,hand.M12,hand.M13,hand.M21,hand.M22,hand.M23,hand.M31,hand.M32,hand.M33}});}report.Add(new{clip,renderer.Duration,frames});}File.WriteAllText(Program.Root+"/Preview/Pack poses.json",JsonSerializer.Serialize(report,new JsonSerializerOptions{WriteIndented=true}));
 }
}




